COURSES[2] = [
S('Pravděpodobnost jako základ rozhodnutí', (1,2), 'Stejné měření může pocházet z různých tříd. Bayesovské rozhodování propojuje model měření, apriorní znalost a cenu chyby.|Postupně zavedeme jevy, podmíněnou pravděpodobnost, posterior a rozhodnutí s nejmenší očekávanou ztrátou.', diagram='bayes-flow'),
S('Množiny a jevy', (3,9), 'Jev je množina výsledků experimentu. Sjednocení znamená „alespoň jeden“, průnik „oba současně“ a doplněk „jev nenastal“.|Například pro A={1,2,3} a B={3,4,5} je průnik {3} a rozdíl A∖B={1,2}. Disjunktní jevy nemají společný výsledek.', [r'A\setminus B=A\cap B^c',r'A\cap B=\varnothing'], diagram='sets'),
S('Pravidla pro množiny', (10,12), 'Sjednocení i průnik jsou komutativní a asociativní. Distribuční a absorpční zákony umožňují přepsat tentýž jev více způsoby.|De Morganovy zákony vysvětlují, jak se při doplňku zamění sjednocení za průnik.', [r'(A\cup B)^c=A^c\cap B^c',r'(A\cap B)^c=A^c\cup B^c']),
S('Klasický a axiomatický pohled', (13,16), 'V konečném prostoru stejně pravděpodobných výsledků je pravděpodobnost poměr příznivých a všech výsledků. Mimo tento předpoklad samotné počítání možností nestačí.|Axiomaticky je pravděpodobnost nezáporná, jistý jev má míru jedna a míry spočetně mnoha disjunktních jevů se sčítají.', [r'P(A)=\frac{|A|}{|\Omega|}',r'P(A\cup B)=P(A)+P(B)-P(A\cap B)']),
S('Relativní četnost', (17,18), 'Z n opakování zaznamenáme nₐ výskytů jevu A. Jejich podíl je empirická relativní četnost — odhad pravděpodobnosti z konkrétního souboru pokusů.|Konečný výsledek kolísá. Zákon velkých čísel popisuje konvergenci za příslušných předpokladů, například u nezávislých stejně rozdělených pokusů; neříká, že se každý další odhad musí zlepšit.', [r'\widehat p_n(A)=\frac{n_A}{n}',r'\widehat p_n(A)\xrightarrow{\mathrm{a.s.}}P(A)'], 'Když A nastalo 37krát ze 100 pokusů, odhad je 0,37. Po dalším pokusu se může od skutečné hodnoty vzdálit. Původní upozornění na kolísání tedy není popřením zákona velkých čísel.', diagram='frequency'),
S('Podmíněná pravděpodobnost', (19,22), 'Podmínka B zúží uvažovaný prostor na situace, ve kterých B nastalo. Pro kladné P(B) znovu normalizujeme pravděpodobnost průniku.|Nezávislost znamená, že tato informace pravděpodobnost A nemění. Párová nezávislost více jevů ještě obecně nezaručuje jejich společnou nezávislost.', [r'P(A\mid B)=\frac{P(A\cap B)}{P(B)}',r'P(A\cap B)=P(A)P(B)']),
S('Úplná pravděpodobnost', (20,22), 'Vzájemně disjunktní jevy Aᵢ pokryjí všechny možnosti. Pravděpodobnost B získáme součtem přes všechny tyto cesty.|To je jmenovatel, který budeme potřebovat pro přepočet pravděpodobnosti třídy po pozorování.', [r'P(B)=\sum_i P(B\mid A_i)P(A_i)'], diagram='probability-tree'),
S('Bayesova věta', (23,25), 'Pravděpodobnost příčiny po pozorování není totéž co pravděpodobnost pozorování při známé příčině. Bayesova věta mezi nimi převádí pomocí prioru a evidence.|Důkaz dostaneme dvojím rozepsáním stejného průniku A∩B.', [r'P(A\mid B)=\frac{P(B\mid A)P(A)}{P(B)}',r'P(A\cap B)=P(B\mid A)P(A)'], 'Posterior = věrohodnost × prior / evidence. Evidence normalizuje součet posteriorních pravděpodobností na jednu.'),
S('Náhodná veličina a distribuční funkce', (26,28), 'Náhodná veličina přiřazuje výsledkům experimentu čísla. Distribuční funkce udává pravděpodobnost hodnot nejvýše x; je neklesající, zprava spojitá a má krajní limity 0 a 1.|Pokud existuje hustota, pravděpodobnost intervalu získáme integrací. Hodnota hustoty v bodě sama není pravděpodobností tohoto bodu.', [r'F_X(x)=P(X\le x)',r'F_X(x)=\int_{-\infty}^{x} f_X(t)\,dt']),
S('Moment, rozptyl a medián', (29,31), 'Střední hodnota shrnuje polohu rozdělení, rozptyl průměrnou čtvercovou odchylku. Medián dělí pravděpodobnost na dvě poloviny a nemusí být jednoznačný.|U diskrétní veličiny nahrazujeme integrály součty. Smíšené rozdělení může mít současně bodové hmoty i spojitou část.', [r'\operatorname{Var}(X)=E[(X-E[X])^2]',r'E[X]=\sum_i x_i P(X=x_i)']),
S('Společné, podmíněné a marginální rozdělení', (32,34), 'Společné rozdělení nese vztahy více veličin. Podmíněním jednu informaci fixujeme; marginalizací ji naopak odstraníme součtem nebo integrálem.|Zákon iterované střední hodnoty umožňuje nejprve průměrovat při známé podmínce a pak přes její rozdělení.', [r'p_X(x)=\int p_{X,Z}(x,z)\,dz',r'E[Y]=E_X[E[Y\mid X]]']),
S('Gaussovský vektor', (35,37), 'Vícerozměrné normální rozdělení popisuje střed μ a kovariance Σ. V regulárním případě je Σ pozitivně definitní.|Lineární transformace i marginály zůstávají normální. U společně normálního vektoru znamená diagonální kovariance nezávislost souřadnic; u obecných rozdělení tato implikace neplatí.', [r'X\sim\mathcal N(\mu,\Sigma)',r'\Sigma=E[(X-\mu)(X-\mu)^\top]'], diagram='gaussian'),
S('Pozitivní nález není automaticky vysoký posterior', (38,42), 'Původní didaktický příklad používá P(C)=0,014, P(+|C)=0,75 a P(+)=0,11. Po dosazení dostaneme přibližně 9,55 %.|Jde o čísla z historického výukového příkladu, nikoli aktuální klinické údaje nebo doporučení pro konkrétního pacienta.', [r'P(C\mid +)=\frac{0.75\cdot0.014}{0.11}',r'P(C\mid +)\approx0.09545'], 'V tomto příkladu je 0,11 celková pravděpodobnost pozitivního výsledku. Není to falešně pozitivní míra. Právě jejich záměna vede k chybnému výsledku.'),
S('Statistický model třídy', (43,44), 'Model potřebuje prior πᵢ a podmíněnou hustotu nebo hmotnostní funkci p(x|ωᵢ). Jejich směs tvoří rozdělení pozorování.|Nejprve z dat získáme posterior. Teprve další krok určí nejlepší akci podle ztrátové funkce.', [r'p(x)=\sum_{i=1}^{K}\pi_i p(x\mid\omega_i)',r'P(\omega_i\mid x)=\frac{\pi_i p(x\mid\omega_i)}{p(x)}']),
S('Bez informace a se stejnými priory', (45,47), 'Pokud je pozorování pro všechny třídy stejně pravděpodobné, nezískali jsme rozlišující informaci a rozhodují priory.|Pokud jsou naopak priory stejné, pořadí tříd určí jejich věrohodnosti. To není důvod používat stejné priory v každé reálné úloze.'),
S('MAP rozhodnutí a logaritmické skóre', (48,51), 'Při stejné ceně všech omylů vybereme nejpravděpodobnější třídu po pozorování. Společnou evidenci p(x) lze při porovnání vynechat.|Logaritmy umožní počítat skóre bez násobení mnoha malých čísel. Remízu je třeba řešit předem určeným pravidlem.', [r'\widehat\omega(x)=\arg\max_i P(\omega_i\mid x)',r'g_i(x)=\log p(x\mid\omega_i)+\log\pi_i']),
S('Matice ztrát a podmíněné riziko', (52,54), 'Položka cᵢⱼ je cena volby i, když skutečná třída je j. Podmíněné riziko je průměr této ceny přes posteriorní rozdělení pravé třídy.|Bayesovská akce minimalizuje riziko pro právě pozorované x. Integrované přes rozdělení dat pak minimalizuje i celkové očekávané riziko.', [r'R(i\mid x)=\sum_j c_{ij}P(\omega_j\mid x)',r'\widehat a(x)=\arg\min_i R(i\mid x)'], diagram='loss'),
S('Nulová–jednotková ztráta', (55,55), 'Správná volba stojí 0 a omyl 1. Riziko volby třídy i je proto jedna minus její posterior.|Za tohoto konkrétního modelu ztrát je minimalizace rizika totéž co minimalizace pravděpodobnosti chyby. Obecná nákladová matice může vést k jiné volbě.', [r'R(i\mid x)=1-P(\omega_i\mid x)',r'e^*(x)=1-\max_i P(\omega_i\mid x)']),
S('Minimax při neznámých priorech', (56,64), 'Když se prior mění nebo jej neznáme, můžeme hledat pravidlo s co nejmenším nejhorším rizikem. U pevné hranice je riziko lineární funkcí prioru.|Minimax chrání proti nejhoršímu případu, ale nemusí být nejlepší pro skutečný známý prior. Tyto dvě optimalizační úlohy nemají stejný cíl.', [r'\delta_{\mathrm{mm}}=\arg\min_\delta\max_{\pi}R(\delta,\pi)'], diagram='minimax'),
S('Možnost nerozhodnout', (65,69), 'Klasifikátor může mít také zamítací akci s konstantní cenou cᵣ. Pak třídu přijme jen tehdy, když její nejmenší riziko nepřekročí cenu zamítnutí.|Pro nulovou–jednotkovou ztrátu to znamená požadovat dostatečně vysoký největší posterior. Zamítnutí není další běžnou třídou objektů.', [r'\min_i R(i\mid x)\le c_r',r'\max_i P(\omega_i\mid x)\ge1-c_r'], 'Při cᵣ=0,2 se přijímá nejlepší posterior alespoň 0,8. Ostatní případy putují k dalšímu měření nebo odbornému posouzení.', diagram='reject'),
S('Rozhodování se dvěma třídami', (70,70), 'Porovnáme rizika obou voleb. Jestliže jsou rozdíly cen omylů kladné, lze podmínku vyjádřit prahem poměru věrohodností.|Na pravé straně působí jak apriorní četnosti, tak cena jednotlivých chyb.', [r'\frac{p(x\mid\omega_1)}{p(x\mid\omega_2)}>\tau',r'\tau=\frac{(c_{12}-c_{22})\pi_2}{(c_{21}-c_{11})\pi_1}']),
S('Více tříd a rozhodovací oblasti', (71,77), 'Stejná myšlenka funguje pro K tříd: každá akce má své riziko a vybereme nejmenší. U symetrické ztráty rozhoduje největší posterior.|Při zamítání vedle oblastí přijatých tříd sledujeme i oblast zamítnutí. Chybovost mezi přijatými případy nesmíme zaměnit za podíl chyb ze všech případů.', [r'A=P(\text{přijetí}),\qquad Q=1-A'], diagram='regions'),
S('Celková pravděpodobnost chyby', (78,81), 'Podmíněnou chybu je třeba zprůměrovat přes všechny možné vstupy. Pro rozhodnutí s nulovou–jednotkovou ztrátou se správná klasifikace získá integrací nad oblastmi správných tříd.|Bayesova chyba je dolní mez pro daná skutečná rozdělení a zvolenou informaci. Odhadnutý klasifikátor této meze nemusí dosáhnout.', [r'P_e=E_X[e(X)]',r'P_{\mathrm{correct}}=\sum_i\int_{S_i}\pi_i p(x\mid\omega_i)\,dx']),
S('Horní mez chyby při zamítání', (82,83), 'Jestliže je podmíněná chyba každého přijatého případu nejvýše cᵣ, platí pro chyby ze všech případů mez cᵣ·A.|Připočteme-li cenu zamítnutých případů, celkové riziko nepřekročí cᵣ. Jde o tvrzení pro správný posterior a deklarovanou ztrátu, ne automatickou garanci neověřeného modelu.', [r'P(\text{chyba a přijetí})\le c_r A',r'R\le c_r A+c_r(1-A)=c_r']),
S('Volba apriorních pravděpodobností', (84,85), 'Prior může vycházet z cílové populace, dřívější klasifikace nebo kontextu. Vyvážený trénovací soubor nemusí mít stejnou četnost tříd jako nasazení.|Rovnoměrný prior je volba modelu, nikoli důsledek neexistence informace. Změnu prioru je třeba odlišovat od změny podmíněných rozdělení.'),
S('Diskrétní a binární příznaky', (86,89), 'Pro diskrétní data nahrazujeme integrály součty. U podmíněně nezávislých binárních příznaků dostaneme součin Bernoulliho pravděpodobností.|Logaritmus poměru věrohodností je pak lineární v binárních souřadnicích. Nezávislost musí platit při známé třídě.', [r'P(x\mid\omega_i)=\prod_j p_{ij}^{x_j}(1-p_{ij})^{1-x_j}']),
S('Hlasy binárních příznaků', (90,91), 'Pokud má příznak stejnou pravděpodobnost jedničky v obou třídách, jeho váha je nulová. Větší pravděpodobnost jedničky v první třídě dává kladný příspěvek pro první třídu.|Konstantní člen obsahuje i prior. Hlasování tedy není pouhé počítání jedniček bez ohledu na jejich význam.', [r'g(x)=b+\sum_j w_jx_j',r'w_j=\log\frac{p_{1j}(1-p_{2j})}{p_{2j}(1-p_{1j})}'])
]

COURSES[3] = [
S('Rodina statistických klasifikátorů', (1,2), 'Jedna rozhodovací teorie vede k různým klasifikátorům podle toho, jak modelujeme rozdělení a kovariance.|Projdeme Gaussovské modely, jejich výpočet, transformace, lineární učení, sousedy a kontext.'),
S('Normální hustota a geometrie', (3,6), 'Střed μᵢ určuje polohu a kovariance Σᵢ tvar hladin stejné hustoty. Pro regulární hustotu je kovariance pozitivně definitní.|Mahalanobisova vzdálenost měří odchylku relativně k rozptylu a korelacím. Délky poloos hladiny jsou úměrné odmocninám vlastních čísel kovariance.', [r'd_i^2=(x-\mu_i)^\top\Sigma_i^{-1}(x-\mu_i)',r'\log p_i(x)=-\tfrac12 d_i^2-\tfrac12\log|\Sigma_i|-\tfrac d2\log(2\pi)'], 'Přednáška někdy nazývá kvadratickou formu vzdáleností. Zde ji důsledně značíme d²; skutečná vzdálenost je její odmocnina.', diagram='gaussian'),
S('Plný Gaussovský klasifikátor', (7,7), 'Při různých kovariancích se v rozdílu logaritmických skóre obecně nezruší kvadratický člen. Rozhodovací hranice proto může být kvadratická.|Rovnoměrný prior odstraní pouze člen log πᵢ. Neodstraní rozdíly determinantů a tvarů rozdělení.', [r'g_i(x)=-\tfrac12 d_i^2-\tfrac12\log|\Sigma_i|+\log\pi_i']),
S('Eukleidovský klasifikátor', (8,11), 'Společná sférická kovariance znamená stejné rozptyly ve všech směrech. Při stejných priorech vybíráme nejbližší střed.|Hranicí je osa dvojice středů. Nerovné priory hranici posunou; neudělají z ní za těchto předpokladů kvadratickou plochu.', [r'\Sigma_i=\sigma^2 I',r'g_i(x)=\frac{\mu_i^\top x}{\sigma^2}-\frac{\|\mu_i\|^2}{2\sigma^2}+\log\pi_i'], diagram='boundary'),
S('Společná kovariance a Mahalanobis', (12,13), 'Při společné plné kovarianci mají všechny třídy stejný elipsoidální tvar. Vzniká lineární hranice, jejíž normála zahrnuje inverzi kovariance.|Eukleidovskou vzdálenost lze chápat jako zvláštní případ, nikoli jako univerzálně vhodnou metriku.', [r'w_{ij}=\Sigma^{-1}(\mu_i-\mu_j)',r'g_i(x)=\mu_i^\top\Sigma^{-1}x-\tfrac12\mu_i^\top\Sigma^{-1}\mu_i+\log\pi_i']),
S('Zjednodušení není totéž co ekvivalence', (14,15), 'Linearizovaný Bayesovský klasifikátor zjednodušuje obecné skóre; není obecně identický s plným kvadratickým pravidlem.|Diagonální kovariance dovoluje samostatně normalizovat jednotlivé příznaky. Při třídně odlišných diagonálách mohou zůstat kvadratické hranice.', [r'd_i^2=\sum_j\frac{(x_j-\mu_{ij})^2}{\sigma_{ij}^2}'], 'Zdroj rozlišuje ztrátové aproximace a bezeztrátové způsoby výpočtu. Zrychlení je třeba hodnotit spolu s tím, zda změnilo model.'),
S('Naivní Bayes', (16,21), 'Předpokládáme podmíněnou nezávislost příznaků při známé třídě. Každou jednorozměrnou složku pak odhadneme zvlášť.|Výpočet a počet parametrů jsou malé, ale závislé příznaky mohou tutéž informaci započítat opakovaně. Dobrá klasifikace ještě nezaručuje kalibrovaný posterior.', [r'p(x\mid\omega_i)=\prod_j p(x_j\mid\omega_i)',r'g_i(x)=\log\pi_i+\sum_j\log p(x_j\mid\omega_i)']),
S('Polonaivní modely', (22,24), 'Podklad rozšiřuje naivní model o závislost na rodičovském příznaku, společného superrodiče nebo výběr méně závislých příznaků.|U superrodiče musí součin obsahovat také jeho vlastní pravděpodobnost. Závislosti je třeba popsat konzistentním rozkladem.', [r'p(x\mid\omega)=p(x_s\mid\omega)\prod_{j\ne s}p(x_j\mid x_s,\omega)']),
S('Kvadratická klasifikace bez změny rozhodnutí', (25,28), 'Bezeztrátové zrychlení zachovává plné skóre. Choleského rozklad dovolí řešit trojúhelníkovou soustavu místo explicitního vytváření inverze.|Kvadratickou formu lze také omezit vlastními čísly. Jestliže se bezpečné intervaly skóre nepřekrývají, některé kandidáty lze vyřadit dříve.', [r'\Sigma=LL^\top,\qquad Ly=x-\mu',r'd^2=\|y\|^2',r'\lambda_{\min}\|v\|^2\le v^\top Av\le\lambda_{\max}\|v\|^2']),
S('Regulární afinní transformace', (29,35), 'Použijeme stejnou invertibilní transformaci na data, středy i kovariance. Mahalanobisova kvadratická forma zůstane stejná.|Hustota se změní společným faktorem daným determinantem. Při porovnání tříd se tento faktor zruší.', [r'z=Qx+r,\qquad\mu_i^{\prime}=Q\mu_i+r',r'\Sigma_i^{\prime}=Q\Sigma_iQ^\top',r'p_z(z\mid\omega_i)=\frac{p_x(x\mid\omega_i)}{|\det Q|}'], diagram='affine'),
S('Která zjednodušení přežijí transformaci', (36,45), 'Plný Gaussovský i společnokovarianční model jsou při regulární afinní transformaci uzavřené rodiny. Eukleidovský model zachová svůj tvar při ortogonálním otočení, ale obecné škálování už může vyžadovat jinou metriku.|Diagonální kovariance obecné otočení nezachová. Korelační pravidlo závislé na normách středů vyžaduje další podmínky. Zmenšení rozměru není invertibilní a obecnou záruku ekvivalence nemá.', comment='Stejné rozhodnutí po správné transformaci není totéž co použití původního eukleidovského pravidla na libovolně přeškálované souřadnice.'),
S('Sekvence nezávislých měření', (46,48), 'Pro více podmíněně nezávislých pozorování se logaritmy poměrů věrohodností sčítají. Opakování může stabilizovat rozhodnutí, pokud opravdu přináší novou informaci.|U nezávislých stejně rozdělených členů klesá rozptyl jejich průměru jako 1/m. U silně korelovaných snímků nelze tento přínos automaticky očekávat.', [r'\Lambda=\sum_{t=1}^{m}\log\frac{p(x_t\mid\omega_1)}{p(x_t\mid\omega_2)}',r'\operatorname{Var}(\overline Z)=\frac{\operatorname{Var}(Z)}{m}']),
S('Fisherův směr', (49,53), 'Hledáme projekci s velkou vzdáleností třídních středů a malým rozptylem uvnitř tříd. Směr je určen pouze do měřítka.|Prahování projekce je další krok: závisí na priorech, ztrátách či validačním kritériu.', [r'J(w)=\frac{(w^\top(\mu_1-\mu_2))^2}{w^\top S_Ww}',r'w\propto S_W^{-1}(\mu_1-\mu_2)'], diagram='projection'),
S('Učení metodou nejmenších čtverců', (54,56), 'Třídy zakódujeme cílovými vektory a minimalizujeme čtvercovou odchylku skóre od těchto cílů. Konstantu lze přidat jako další souřadnici.|Normální rovnice je vhodné řešit stabilní faktorizací, při singularitě pseudoinverzí nebo regularizací.', [r'\min_W\|YW-U\|_F^2',r'Y^\top YW=Y^\top U']),
S('Regresní klasifikátor', (57,60), 'Lineární regrese může mapovat vstup do prostoru kódů tříd. Nový bod přiřadíme k nejbližšímu cílovému kódu nebo největšímu skóre.|Kvadratické rozšíření zvýší flexibilitu i počet parametrů. Nejmenší trénovací reziduum však samo o sobě nevybírá nejlepší klasifikátor.'),
S('Geometrické rozhodování', (61,64), 'Lineární diskriminační funkce lze učit i bez předpokladu hustot. Pro dvojici tříd dává rozdíl vah normálu oddělující nadroviny.|Přednáška připomíná také iterativní Ho–Kashyapův postup. Zda lineární oddělení vůbec existuje, je vlastnost konkrétních dat.', [r'h_{ij}:\ (w_i-w_j)^\top x+b_i-b_j=0'], diagram='boundary'),
S('Nejbližší prototyp', (65,66), 'Každá třída může mít několik reprezentantů. Bod přidělíme ke třídě nejbližšího prototypu.|Voroného oblasti jsou pro eukleidovskou metriku po částech lineární. Sloučením více oblastí stejné třídy může vzniknout složitější třídní oblast.', [r'j^*=\arg\min_j\|x-p_j\|^2'], diagram='neighbors'),
S('Nelinearita přes nové příznaky', (67,70), 'Vektor φ(x) může obsahovat mocniny a součiny původních souřadnic. Skóre zůstává lineární v parametrech, ale hranice je nelineární v původním prostoru.|Počet členů rychle roste. Mapování také nevytvoří nezávislou novou informaci: jeho obraz může ležet na nízkorozměrné množině.', [r'\phi(x_1,x_2)=(x_1,x_2,x_1^2,x_1x_2,x_2^2)',r'g(x)=w^\top\phi(x)+b']),
S('Pravoúhlé rozhodovací oblasti', (71,71), 'Paralelopipedový klasifikátor omezuje přípustný interval každého příznaku. Test je levný a snadno interpretovatelný.|Oblasti se mohou překrývat nebo mezi nimi mohou být mezery. Implementace musí určit volbu při překryvu i zacházení s bodem mimo všechny intervaly.'),
S('Parzenův klasifikátor', (72,72), 'Hustotu třídy odhadneme jako průměr jader soustředěných do trénovacích bodů. Potom použijeme stejné Bayesovské porovnání jako dříve.|Šířka jádra ovládá vyhlazení: malé jádro dává špičatý odhad, příliš velké rozmaže strukturu. Cena vyhodnocení roste s počtem prototypů.', [r'\widehat p_i(x)=\frac1{n_i h^d}\sum_{j=1}^{n_i}K\!\left(\frac{x-x_{ij}}h\right)']),
S('Jeden a k nejbližších sousedů', (73,77), 'Pravidlo 1-NN přebírá třídu nejbližšího trénovacího bodu. k-NN hlasuje mezi k nejbližšími.|Je třeba určit metriku, škálování, řešení remíz a případné vážení vzdáleností. Větší k vyhlazuje hranici, ale může potlačit malé oblasti.', [r'\widehat y=\operatorname{majority}\{y_j:j\in N_k(x)\}'], diagram='neighbors'),
S('Co sousedé nezaručují', (78,79), 'S rostoucím vzorkem se blízcí sousedé přibližují dotazu za odpovídajících předpokladů. To samo neříká, že každý konečný k-NN dosáhne Bayesovy chyby.|Nadbytečné a špatně škálované příznaky mohou znehodnotit vzdálenost. Velký trénink také zvyšuje paměťovou a výpočetní cenu.', comment='Pro klasickou konzistenci k-NN se typicky uvažuje k rostoucí s n a současně k/n→0. Nelze tuto vlastnost přenést na libovolné pevné k bez dalších podmínek.'),
S('Kontext mění rozhodnutí', (80,81), 'Třídu pixelu nebo prvku může ovlivňovat sousedství, topologie i externí mapa. Kontext lze použít při klasifikaci i při následné reklasifikaci.|Globální posterior nad všemi prvky bývá příliš složitý. Proto potřebujeme explicitní lokální předpoklady.', diagram='context'),
S('Markovské zjednodušení', (82,89), 'Markovský model omezuje závislosti na lokální okolí. Podmíněná nezávislost měření při známých třídách dovolí rozdělit část pravděpodobnostního modelu na lokální členy.|Původní odvození porovnává několik kombinací těchto předpokladů. Odhad pravděpodobnosti okolních tříd není totéž co znalost jejich skutečných hodnot.', [r'P(y_r\mid y_{-r})=P(y_r\mid y_{N(r)})'], 'Silné vyhlazení může odstranit malé skutečné objekty. Kontextový model proto není pouze filtr, který má za každou cenu sjednotit sousední štítky.')
]

COURSES[4] = [
S('Jak se model učí z dat', (1,3), 'Rozhodovací pravidlo potřebuje parametry nebo celá rozdělení. Učení je jejich odhad z dostupných pozorování.|Projdeme bodové i Bayesovské odhady, neparametrické hustoty, neoznačené směsi, EM a volbu trénovacích dat.'),
S('Co znamená učit se', (4,13), 'Učení s učitelem používá označená data, bez učitele hledá strukturu. Transfer využívá předchozí model pro novou úlohu; jeho vhodnost závisí na vztahu domén.|Přednáška zdůrazňuje také férovost a změnu prostředí. Velký soubor nemůže automaticky napravit systematicky chybné či nereprezentativní označení.'),
S('Parametrický a neparametrický přístup', (14,15), 'Parametrický model předem volí rodinu rozdělení a učí konečný počet parametrů. Neparametrický model dovoluje strukturu více přizpůsobit datům.|Flexibilita ale není zdarma: potřebujeme dost dat, vhodné vyhlazení a kontrolu složitosti. Oba přístupy obsahují předpoklady.'),
S('Klasická a Bayesovská statistika', (16,19), 'V klasickém pojetí jsou parametry pevné neznámé hodnoty a hodnotíme opakované použití odhadu. Bayesovské pojetí pracuje s jejich priorním a posteriorním rozdělením.|Množství známé informace určuje úlohu: od hotového klasifikátoru přes označené či částečně označené vzorky až po zcela neoznačenou směs.'),
S('Identifikovatelnost', (20,20), 'Parametr lze jednoznačně obnovit z rozdělení jen tehdy, pokud různé parametry nepopisují stejné pozorovatelné rozdělení.|U směsí běžně nerozlišujeme přejmenování komponent. Závažnější neidentifikovatelnost nastává, když ani po této ekvivalenci nelze jednotlivé komponenty odvodit.', [r'p_\theta=p_{\theta^\prime}\ \Longrightarrow\ \theta=\theta^\prime'], 'Dostatek dat snižuje náhodnou chybu, ale neodstraní neidentifikovatelnost zabudovanou do modelu.'),
S('Co je odhad', (21,25), 'Odhad je funkce náhodného výběru. Jeho hodnota se mezi výběry mění, i když je skutečný parametr stejný.|Momentová metoda, minimum χ², věrohodnost a Bayesovský odhad optimalizují různá kritéria. Nelze je zaměnit jen podle toho, který dává hezčí číslo.', [r'\widehat\theta=T(X_1,\ldots,X_n)']),
S('Vychýlení a konzistence', (26,28), 'Nestranný odhad má střední hodnotu rovnou pravému parametru. Konzistence znamená přibližování odhadu pravé hodnotě s rostoucím množstvím dat v určeném smyslu konvergence.|Ani malá variance nezaručuje malé vychýlení. Konzistentní odhad také nemusí být nestranný pro každý konečný vzorek.', [r'\operatorname{bias}(\widehat\theta)=E[\widehat\theta]-\theta',r'\widehat\theta_n\xrightarrow{P}\theta']),
S('Variance, MSE a efektivita', (29,36), 'Střední kvadratická chyba kombinuje rozptyl odhadu a jeho vychýlení. Proto může mírně vychýlený odhad být užitečnější než nestranný s velkou variancí.|Cramérova–Raova mez omezuje varianci nestranných odhadů za příslušných regularitních předpokladů. Dosažení meze se nazývá efektivita.', [r'\operatorname{MSE}=\operatorname{Var}(\widehat\theta)+\operatorname{bias}(\widehat\theta)^2',r'\operatorname{Var}(\widehat\theta)\ge I_n(\theta)^{-1}'], diagram='bias-variance'),
S('Postačující statistika', (30,31), 'Postačující statistika uchovává ve vzorku všechnu informaci relevantní k parametru v daném modelu. Nejde o univerzální kompresi pro libovolnou budoucí úlohu.|Například u Bernoulliho pokusů se společným parametrem stačí pro jeho odhad znát počet úspěchů a velikost výběru.', [r'p(T\mid\theta)=g(s(T),\theta)h(T)']),
S('Momentová metoda', (37,39), 'Teoretické momenty ztotožníme s výběrovými a vyřešíme rovnice pro parametry. U normálního rozdělení tak dostaneme výběrový průměr a rozptyl s dělením n.|Metoda vyžaduje existenci příslušných momentů. Například Cauchyho rozdělení nemá běžnou konečnou střední hodnotu ani rozptyl.', [r'\widehat\mu=\frac1n\sum_j x_j',r'\widehat\sigma^2_{\mathrm{ML}}=\frac1n\sum_j(x_j-\widehat\mu)^2']),
S('Minimum χ²', (40,41), 'Pozorování rozdělíme do intervalů. Porovnáváme jejich skutečné četnosti nᵢ s očekávanými n·pᵢ(θ).|Volbou parametrů minimalizujeme vážené odchylky. Vzorec vyžaduje kladné očekávané četnosti; kvantování a malé počty mohou ovlivnit výsledek.', [r'\widehat\theta=\arg\min_\theta\sum_i\frac{(n_i-np_i(\theta))^2}{np_i(\theta)}']),
S('Maximální věrohodnost a MAP', (42,44), 'ML vybírá parametr, při kterém jsou pozorovaná data nejvěrohodnější. U nezávislých vzorků přejdeme od součinu k součtu logaritmů.|MAP přidává prior parametru. Pseudověrohodnost je jiné zjednodušené kritérium a vyžaduje vlastní zdůvodnění.', [r'\ell(\theta)=\sum_j\log p(x_j\mid\theta)',r'\widehat\theta_{\mathrm{MAP}}=\arg\max_\theta[\ell(\theta)+\log p(\theta)]']),
S('Bayesovská predikce', (45,48), 'Posterior parametru kombinuje prior s věrohodností trénovacích dat. Pro nové pozorování integrujeme přes zbývající nejistotu o parametru.|Nová data lze zapracovat rekurzivně: včerejší posterior se stane dnešním priorem. Konvergence vyžaduje předpoklady modelu a nelze ji slibovat bez nich.', [r'p(\theta\mid T)\propto p(T\mid\theta)p(\theta)',r'p(x\mid T)=\int p(x\mid\theta)p(\theta\mid T)\,d\theta']),
S('Odhad závisí na ztrátě', (49,49), 'Pro kvadratickou ztrátu minimalizuje posteriorní očekávanou ztrátu posteriorní průměr. Absolutní ztráta vede k posteriornímu mediánu.|Maximum posteriorní hustoty je MAP, ale není automaticky optimální pro libovolnou ztrátovou funkci.', [r'\widehat\theta_{L_2}=E[\theta\mid T]']),
S('Histogram jako odhad hustoty', (50,50), 'Počet prvků v buňce převedeme na pravděpodobnostní hmotu dělením počtem pozorování. Pro hustotu musíme navíc dělit objemem buňky.|Při k intervalech v každém z d rozměrů vznikne kᵈ buněk. Ve velkém rozměru bývá většina z nich prázdná.', [r'\widehat p(x)=\frac{n_{\mathrm{bin}}}{nV_{\mathrm{bin}}}',r'N_{\mathrm{bins}}=k^d']),
S('Parzenův odhad a šířka jádra', (51,55), 'Každé pozorování nahradíme normalizovaným nezáporným jádrem a všechna zprůměrujeme. Gaussovské, kulové a krychlové jádro se liší tvarem i chováním hranic.|Pro konzistenci se obvykle nechává šířka h klesat, ale počet vzorků v lokálním objemu musí růst. Příliš malá i příliš velká šířka mají své chyby.', [r'\widehat p(x)=\frac1{nh^d}\sum_j K\!\left(\frac{x-x_j}{h}\right)',r'h\to0,\qquad nh^d\to\infty'], diagram='kde'),
S('Neoznačená data: módy nebo směs', (56,59), 'Můžeme hledat oddělené módy rozdělení, nebo předpokládat směs parametrických komponent. Výsledek závisí na tom, co model považuje za shluk.|UNISEP promítá data do směrů vlastních vektorů, hledá minima mezi módy histogramu a rekurzivně rozděluje soubor. Šum a projekce mohou vytvářet nebo skrývat zdánlivé módy.'),
S('Směsi a nejednoznačnost', (60,65), 'Pozorujeme pouze součet vážených komponent, nikoli jejich označení. Přejmenování komponent samo o sobě rozdělení nezmění.|U dvousložkové Bernoulliho směsi se stejnými vahami určuje pozorování pouze průměr parametrů. Dvojice 0,2 a 1,0 může dát stejnou směs jako 0,6 a 0,6.', [r'p(x)=\sum_{k=1}^{K}\pi_k p(x\mid\theta_k)',r'P(X=1)=\tfrac12(\theta_1+\theta_2)']),
S('Momentová metoda pro směs', (66,66), 'Momenty směsi jsou vážené součty momentů jejích komponent. U Gaussovské směsi druhý moment obsahuje rozptyl i čtverec středu.|Samotný počet rovnic nestačí: řešení může být nejednoznačné nebo nestabilní. Pozorovatelný střed směsi není středem každé komponenty.', [r'E[X]=\sum_k\pi_k\mu_k',r'E[X^2]=\sum_k\pi_k(\sigma_k^2+\mu_k^2)']),
S('Proč je učení směsi provázané', (67,68), 'Při maximální věrohodnosti neoznačené směsi se uvnitř každého logaritmu sčítají všechny komponenty. Parametry proto nelze jednoduše odhadnout po třídách nezávisle.|Latentní přiřazení pozorování ke komponentám vede k algoritmu EM.', [r'\ell(\theta)=\sum_j\log\!\left(\sum_k\pi_k p(x_j\mid\theta_k)\right)']),
S('EM: očekávání a maximalizace', (69,69), 'V E-kroku odhadneme posteriorní rozdělení skrytých proměnných při současných parametrech. V M-kroku maximalizujeme očekávanou úplnou logaritmickou věrohodnost.|Střídáme doplnění neznámé informace a aktualizaci parametrů. Nejde obecně o tvrdé přiřazení každého bodu jedné třídě.', [r'Q(\theta\mid\theta_t)=E[\log p(X,Z\mid\theta)\mid X,\theta_t]',r'\theta_{t+1}=\arg\max_\theta Q(\theta\mid\theta_t)'], diagram='em'),
S('Číselný příklad neúplného pozorování', (70,70), 'Podklad pracuje s četnostmi (125,18,20,34) a kategoriemi s pravděpodobnostmi (2+α,1−α,1−α,α)/4. První kategorie slučuje dvě skryté možnosti.|Při α=0,5 připadne proměnné části první kategorie očekávaných 25 pozorování. M-krok dá α′=59/97≈0,60825.', [r'\widehat z=125\frac{\alpha}{2+\alpha}',r'\alpha^{\prime}=\frac{\widehat z+34}{\widehat z+34+18+20}']),
S('Vlastnosti a meze EM', (71,73), 'Při přesném E-kroku a odpovídající maximalizaci věrohodnost neklesá. To ale nezaručuje globální optimum ani jediný správný rozklad.|Záleží na inicializaci a regularitě. U Gaussovských směsí může komponenta kolabovat do bodu a vést k degeneraci.', [r'\ell(\theta_{t+1})\ge\ell(\theta_t)']),
S('Diskrétní směs součinových komponent', (74,76), 'Uvnitř každé komponenty lze předpokládat nezávislé diskrétní souřadnice. E-krok určí váhy přiřazení a M-krok z nich počítá vážené četnosti.|Podmíněná nezávislost uvnitř komponent neznamená nezávislost v celé směsi. Marginalizaci lze v tomto modelu provést součtem přes komponenty.', [r'p(x)=\sum_k\pi_k\prod_r p(x_r\mid\theta_k)']),
S('EM pro Gaussovskou směs', (77,80), 'Odpovědnost rⱼₖ říká, nakolik bod j patří komponentě k. Z těchto vah vypočteme efektivní velikost komponenty, její střed a kovarianci.|Kovariance musí být numericky použitelná. Omezení společné kovariance nebo regularizace mění model a mají být explicitní.', [r'N_k=\sum_j r_{jk},\qquad\pi_k^{\prime}=N_k/n',r'\mu_k^{\prime}=\frac1{N_k}\sum_j r_{jk}x_j',r'\Sigma_k^{\prime}=\frac1{N_k}\sum_j r_{jk}(x_j-\mu_k^{\prime})(x_j-\mu_k^{\prime})^\top']),
S('Co nám poskytují označená data', (81,85), 'Známé třídy usnadní oddělené učení komponent; neoznačená směs nese menší informaci o jejich rozkladu. V obou případech rozhoduje reprezentativnost dat.|Vyvažování, podvzorkování, kopírování a syntéza mají odlišné důsledky. Kopie jednoho případu není nové nezávislé pozorování.'),
S('Málo vzorků, mnoho parametrů', (86,89), 'Vzorková kovariance nemusí být při malém n invertibilní. Můžeme snížit rozměr, sdílet kovarianci mezi třídami nebo ji přiblížit stabilnějšímu cíli.|Smrštění k násobku jednotkové matice ponechá průměrné měřítko rozptylu. Sílu regularizace vybíráme na validačních datech.', [r'\Sigma_\lambda=(1-\lambda)\widehat\Sigma+\lambda\tau I',r'\tau=\operatorname{tr}(\widehat\Sigma)/d']),
S('Hughesův jev', (90,92), 'Při pevném množství trénovacích dat nemusí více příznaků znamenat lepší klasifikaci. Zisk informace může převážit narůstající chyba odhadu jen do určité složitosti.|Příznaky i regularizaci vybíráme uvnitř trénovacího procesu. Test zůstává nezávislým závěrečným vyhodnocením.', diagram='bias-variance')
]
